def f(g):
    h,w=len(g),len(g[0])
    cnt=Counter(x for row in g for x in row); bg=cnt.most_common(1)[0][0]
    res=[row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if g[r][c]==bg: continue
            cnts={}
            for dx in(-1,0,1):
                for dy in(-1,0,1):
                    p,qd=r+dx,c+dy
                    if 0<=p<h and 0<=qd<w: cnts[g[p][qd]]=cnts.get(g[p][qd],0)+1
            if len(cnts)==1: continue  # same-color component
            best=max(cnts.values())
            tied=[k for k,v in cnts.items() if v==best]
            res[r][c]=min(tied)  # tie -> smaller color
    return res
