    cnt=Counter(x for row in g for x in row); bg=cnt.most_common(1)[0][0]
    objs=[comp for col in Counter(x for row in g for x in row) if col!=bg
           for comp in comps_of(g,col) if len(comp)>=3]
    objcells={(r,c) for comp in objs for (r,c) in comp}
