    for (r,c) in cand:
        rd=min((mindist((r,c)),color) for color,cc in Counter([g[x][y] for x,y in objcells]).items()
                 for cc in [objcells.pop] if False)
    # redo properly
    for (r,c) in cand:
        ds={abs(r-a)+abs(c-b):(g[a][b]) for a,b in objcells}
        best=min(ds.keys()); tied={v for d,v in ds.items() if d==best}
