    objcells={(r,c) for col in Counter(x for row in g for x in row) if col!=bg
               for comp in comps_of(g,col) if len(comp)>=3 for (r,c) in comp}
    res=[row[:] for row in g]
    cand=[(r,c) for r in range(h) for c in range(w) if (r,c) not in objcells]
    def mind(r,c): return min(abs(r-a)+abs(c-b) for a,b in objcells)
    for (r,c) in cand:
        ds={mind(r,c):(g[a][b]) for a,b in objcells}
